#!/usr/bin/env bun
// The fixture generator (spec v1.2, Appendix B): `fixtures/desk` is *generated by the code*, never
// hand-written. It reads the declared inputs and drives the add-on — the same `ledgerAdd`,
// `captureText`, `captureImage` and `deriveViews` the desk runs — so the shipped fixture can only be
// what the code produces.
//
//   bun apps/dpi-desk/regen-fixture.ts [--inputs fixtures/desk-inputs] [--out fixtures/desk]
//
// Every line of `input.jsonl` is one operation:
//   {"op":"ledger_add",  "project","name","line":{...}}
//   {"op":"capture_text","project","name","input":{...}}
//   {"op":"capture_image","project","name","input":{"path",...}}   // path is relative to --inputs
//   {"op":"derive",      "today":"YYYY-MM-DD"}                     // derive views for every project
// Timestamps (`at`, `updated_at`, `generated_at`) are the only fields a second run may differ in.
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { captureImage, captureText, deriveViews, ledgerAdd } from "../dpi-backend/src/desk-addon.ts";

const flag = (name: string, fallback: string): string => {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
};

const here = dirname(new URL(import.meta.url).pathname);
const repo = resolve(here, "..", "..");
const inDir = resolve(repo, flag("inputs", "fixtures/desk-inputs"));
const outDir = resolve(repo, flag("out", "fixtures/desk"));

if (!existsSync(join(inDir, "input.jsonl"))) {
  console.error(`regen-fixture: no input.jsonl under ${inDir}`);
  process.exit(2);
}

// A clean slate: the fixture is the generator's output, so nothing of a previous run survives.
for (const p of ["projects", "views", "projects.json"]) rmSync(join(outDir, p), { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });

type Op = {
  op: "ledger_add" | "capture_text" | "capture_image" | "derive";
  project?: string;
  name?: string;
  today?: string;
  line?: Record<string, unknown>;
  input?: Record<string, unknown>;
};
const ops = readFileSync(join(inDir, "input.jsonl"), "utf8")
  .split("\n")
  .filter((l) => l.trim() && !l.trimStart().startsWith("#"))
  .map((l) => JSON.parse(l) as Op);

let today = "2026-03-15"; // the fixed "today" of Appendix B, overridable by the `derive` op
for (const o of ops) {
  if (o.op === "derive") today = o.today ?? today;
}

for (const o of ops) {
  if (o.op === "derive") continue;
  const slug = String(o.project ?? "");
  const opts = { root: outDir, slug, name: o.name, today };
  if (o.op === "ledger_add") {
    ledgerAdd((o.line ?? {}) as never, opts);
  } else if (o.op === "capture_text") {
    captureText((o.input ?? {}) as never, opts);
  } else if (o.op === "capture_image") {
    const rel = String((o.input?.path as string) ?? "");
    const path = existsSync(rel) ? rel : join(inDir, rel);
    captureImage({ ...(o.input ?? {}), path } as never, opts);
  }
}

for (const s of readdirSync(join(outDir, "projects"), { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name)) {
  deriveViews(outDir, s, { today });
}

console.log(`regenerated ${outDir} from ${inDir}`);
